// Emits effects/common/hiwatt_cab.h: Comet Flower's datasheet Fane 4x12 cab
// (CabSimMath::design(Model::Fane412, 44100)) as float biquad constants, so
// the G1 cab is the desktop cab by construction. Build: tools/gen_fane_cab.bat
#include <cstdio>
#include "CabSimMath.h"

int main(int argc, char** argv)
{
    const double fs = 44100.0;
    const auto d = CabSimMath::design(CabSimMath::Model::Fane412, fs);
    FILE* f = std::fopen(argc > 1 ? argv[1] : "hiwatt_cab.h", "w");
    std::fprintf(f,
        "/* hiwatt_cab.h - GENERATED by tools/gen_fane_cab.cpp; do not edit.\n"
        " * Comet Flower CabSimMath::design(Model::Fane412, 44100): the datasheet\n"
        " * Fane Crescendo 4x12 the desktop Hiwatt renders, %d biquads at base\n"
        " * rate, unity at 1 kHz (makeup folded into the first section).\n"
        " * Rows: b0 b1 b2 a1 a2 (a0 = 1). */\n"
        "#ifndef HIWATT_CAB_H\n#define HIWATT_CAB_H\n\n"
        "#define HW_CAB_N %d\n\n"
        "static const float hw_cab[HW_CAB_N][5] = {\n", d.numSections, d.numSections);
    for (int i = 0; i < d.numSections; ++i) {
        const auto& c = d.sections[i];
        const double g = (i == 0) ? d.makeupGain : 1.0;
        std::fprintf(f, "    { %.9ef, %.9ef, %.9ef, %.9ef, %.9ef },\n",
                     c.b0 * g, c.b1 * g, c.b2 * g, c.a1, c.a2);
    }
    std::fprintf(f, "};\n\n#endif /* HIWATT_CAB_H */\n");
    std::fclose(f);
    return 0;
}
